<script>document.addEventListener('DOMContentLoaded',()=>{const category=document.getElementById('tax_category'),code=document.getElementById('tax_exemption_reason_code'),text=document.getElementById('tax_exemption_reason');function sync(){const needed=category.value!=='S';document.querySelectorAll('.tax-reason-field').forEach(field=>field.hidden=!needed);code.required=needed;text.required=needed;if(!needed){code.value='';text.value='';}if(category.value==='O')code.value='VATEX-SA-OOS';}category.addEventListener('change',sync);sync();});</script>
